// Generates src/index.ts from the component folders, so parallel work on
// different components never conflicts on a shared barrel file.
import { readdirSync, existsSync, writeFileSync } from "node:fs";

const root = new URL("../src/components/", import.meta.url);
const comps = readdirSync(root, { withFileTypes: true })
  .filter(
    (d) => d.isDirectory() && existsSync(new URL(`${d.name}/index.ts`, root)),
  )
  .map((d) => d.name)
  .sort();

const lines = [
  "// Generated by scripts/build-index.mjs. Do not edit.",
  'export * from "./theme";',
  'export * from "./utils/cx";',
  ...comps.map((c) => `export * from "./components/${c}";`),
  "",
];
writeFileSync(new URL("../src/index.ts", import.meta.url), lines.join("\n"));
console.log(`index: ${comps.length} components`);
